<script setup lang="ts">
import {computed} from 'vue';
const props=defineProps<{modelValue:string,solution:string}>();
const emit=defineEmits<{'update:modelValue':[value:string]}>();
const shape=computed(()=>{try{return JSON.parse(props.solution)}catch{return {}}});
const value=computed(()=>{try{return JSON.parse(props.modelValue)}catch{return undefined}});
function set(key:string,input:string){let v:unknown=input;if(input==='true'||input==='false')v=input==='true';if(key==='order')v=input.split(',');emit('update:modelValue',JSON.stringify({...value.value,[key]:v}));}
const names:Record<string,string>={row:'一行的名称',column:'一列的名称',recoverable:'可恢复',cascadeless:'无级联',dirty:'允许脏读',nonrepeatable:'允许不可重复读',phantom:'允许幻读',conflict_serializable:'冲突可串行化',view_serializable:'视图可串行化',order:'串行顺序'};
function toggle(column:string,checked:boolean){const current=Array.isArray(value.value)?value.value:[];emit('update:modelValue',JSON.stringify(checked?[...current,column]:current.filter((v:string)=>v!==column)));}
</script>
<template><section class="structured-answer"><p>选择判断或字段，系统会自动编码答案。</p><label v-if="typeof shape==='boolean'">是否相同读取机制<select :value="value===undefined?'':String(value)" @change="emit('update:modelValue',($event.target as HTMLSelectElement).value)"><option value="" disabled>请选择</option><option value="true">是</option><option value="false">否</option></select></label><fieldset v-else-if="Array.isArray(shape)"><legend>选择主键列</legend><label v-for="c in ['Sno','Sname','Ssex','Sage','Sdept']" :key="c"><input type="checkbox" :checked="Array.isArray(value)&&value.includes(c)" @change="toggle(c,($event.target as HTMLInputElement).checked)">{{c}}</label></fieldset><template v-else><label v-for="(sample,key) in shape" :key="key">{{names[String(key)]??key}}<select :value="Array.isArray(value?.[key])?value[key].join(','):value?.[key]===undefined?'':String(value[key])" @change="set(String(key),($event.target as HTMLSelectElement).value)"><option value="" disabled>请选择</option><template v-if="typeof sample==='boolean'"><option value="true">是 / 允许</option><option value="false">否 / 不允许</option></template><template v-else-if="Array.isArray(sample)"><option value="T1,T2">T1 → T2</option><option value="T2,T1">T2 → T1</option></template><template v-else><option value="tuple">tuple · 元组</option><option value="attribute">attribute · 属性</option><option value="relation">relation · 关系</option></template></select></label></template></section></template>
